from triton.experimental import gluon
from triton.experimental.gluon import language as gl
import torch

@gluon.jit
def _quantize_group(x, DTYPE: gl.constexpr, FP8_MAX: gl.constexpr):
    scale = gl.div_rn(gl.maximum(gl.max(gl.abs(x), 1), 1e-10), FP8_MAX)
    q = (x * gl.div_rn(1.0, scale)[:, None]).to(DTYPE)
    return (q, scale)

@gluon.jit
def _activate_quantize(X, Q, S, Ids, M: gl.constexpr, K: gl.constexpr, FP8_MAX: gl.constexpr, EP: gl.constexpr, E: gl.constexpr, OFFSET: gl.constexpr):
    ly: gl.constexpr = gl.BlockedLayout([1, 8], [4, 16], [1, 1], [1, 0])
    row = gl.program_id(0) * 4 + gl.arange(0, 4, gl.SliceLayout(1, ly))
    col = gl.program_id(1) * 128 + gl.arange(0, 128, gl.SliceLayout(0, ly))
    owned = row < M
    if EP:
        expert = gl.load(Ids + row, row < M, -1) - OFFSET
        owned &= (expert >= 0) & (expert < E)
    gate = gl.load(X + row[:, None] * 2 * K + col[None, :], owned[:, None], 0).to(gl.float32)
    up = gl.load(X + row[:, None] * 2 * K + K + col[None, :], owned[:, None], 0).to(gl.float32)
    x = (gate * (1.0 / (1.0 + gl.exp(-gate))) * up).to(gl.bfloat16).to(gl.float32)
    q, scale = _quantize_group(x, Q.dtype.element_ty, FP8_MAX)
    gl.store(Q + row[:, None] * K + col[None, :], q, row[:, None] < M)
    gl.store(S + row * (K // 128) + gl.program_id(1), scale, row < M)

@gluon.jit
def _shuffled_offset(n, k, step, WK: gl.constexpr):
    return n[:, None] // 16 * WK * 16 + step * 2048 + k[None, :] // 16 * 256 + n[:, None] % 16 * 16 + k[None, :] % 16

@gluon.jit
def _combine(Y, Weights, Out, Ids, H: gl.constexpr, TOPK: gl.constexpr, EP: gl.constexpr, E: gl.constexpr, OFFSET: gl.constexpr, B: gl.constexpr, NW: gl.constexpr):
    row = gl.program_id(0)
    ly: gl.constexpr = gl.BlockedLayout([4], [64], [NW], [0])
    h = gl.program_id(1) * B + gl.arange(0, B, ly)
    acc = gl.full((B,), 0, gl.float32, ly)
    for slot in gl.static_range(TOPK):
        owned = True
        if EP:
            expert = gl.load(Ids + row * TOPK + slot) - OFFSET
            owned = (expert >= 0) & (expert < E)
        val = gl.load(Y + (row * TOPK + slot) * H + h, (h < H) & owned, 0).to(gl.float32)
        weight = gl.load(Weights + row * TOPK + slot)
        acc += val * weight
    gl.store(Out + row * H + h, acc, h < H)

def _quantization_buffers(rows, width, like):
    q = torch.empty((rows, width), device=like.device, dtype=like.dtype)
    s = torch.empty((rows, width // 128), device=like.device, dtype=torch.float32)
    return (q, s)
